#!/usr/bin/env python3
"""Build the evidence-backed business logic map for Pishkan.

Reads committed source files and imports the seed catalog (Node + workspace tsx),
then emits a single-data-source JSON, standalone RTL HTML and audit report.
No environment values or database contents are read.
"""
from __future__ import annotations
import collections, html, json, re, subprocess
from pathlib import Path
from typing import Any

ROOT=Path(__file__).resolve().parents[1]
OUT_JSON=ROOT/'Pishkan-Business-Logic-Data.json'
OUT_HTML=ROOT/'Pishkan-Business-Logic-Map.html'
OUT_REPORT=ROOT/'Pishkan-Business-Logic-Audit.md'
REPO='khajavy8056/Pishkan'
BRANCH='arena/3ec9e234-pishkan'
COMMIT=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip()
ARCH_PATH=ROOT/'Pishkan-Architecture-Data.json'
ARCH=json.loads(ARCH_PATH.read_text()) if ARCH_PATH.exists() else {"roles":[]}
ROLE_NAMES={r['code']:r.get('name',r['code']) for r in ARCH.get('roles',[])}
ROLE_NAMES.update({'customer':'مشتری','guest':'مهمان','service_expert':'کارشناس خدمت','operator':'اپراتور','document_reviewer':'بازبین مدارک','accountant':'حسابدار','manager':'مدیر داخلی','super_admin':'مدیر کل','staff':'کارمند','system':'سامانه/کار زمان‌بندی‌شده','gateway':'درگاه پرداخت','external_org':'سازمان متولی'})
FILES={}
def text(path:str)->str:
    if path not in FILES:
        p=ROOT/path
        try: FILES[path]=p.read_text(encoding='utf-8')
        except Exception: FILES[path]=''
    return FILES[path]
def ev(path:str,symbol:str='',route:str='',test:str='',note:str='')->dict[str,Any]:
    src=text(path); line=None
    if symbol:
        pos=src.find(symbol)
        if pos>=0: line=src.count('\n',0,pos)+1
    out={'path':path}
    if line: out['line']=line
    if symbol: out['symbol']=symbol
    if route: out['route']=route
    if test: out['test']=test
    if note: out['note']=note
    return out

def load_seed_catalog()->dict[str,Any]:
    js="import {SEED_SERVICES,SEED_CATEGORIES} from './apps/api/src/modules/catalog/seed-data.ts'; console.log(JSON.stringify({services:SEED_SERVICES,categories:SEED_CATEGORIES}));"
    raw=subprocess.check_output(['node','--import','tsx','--input-type=module','-e',js],cwd=ROOT,text=True)
    return json.loads(raw)

nodes:dict[str,dict[str,Any]]={}
edges:list[dict[str,Any]]=[]
edge_keys=set()
FLOW_GROUPS=[]

def add_edge(source:str,target:str,relation:str,label:str='',confidence:str='high',evidence:list[dict[str,Any]]|None=None,**extra:Any):
    if source==target or source not in nodes or target not in nodes: return
    key=(source,target,relation,label)
    if key in edge_keys: return
    edge_keys.add(key)
    e={'id':f'e{len(edges)+1:04d}','source':source,'target':target,'relation':relation,'label':label or relation,'confidence':confidence,'evidence':evidence or []}
    e.update(extra);edges.append(e)

def add_node(id:str,title:str,description:str,category:str,parent:str|None=None,kind:str='action',roles:list[str]|None=None,
             trigger:str='',preconditions:list[str]|None=None,inputs:list[str]|None=None,outputs:list[str]|None=None,
             before:str='',after:str='',success:str='',failure:str='',implementation:str='implemented_untested',
             confidence:str='high',evidence:list[dict[str,Any]]|None=None,notes:list[str]|None=None,**extra:Any):
    assert id not in nodes,id
    node={'id':id,'title':title,'description':description,'category':category,'parentId':parent,'kind':kind,
          'roles':roles or [],'trigger':trigger,'preconditions':preconditions or [],'inputs':inputs or [],'outputs':outputs or [],
          'beforeStatus':before,'afterStatus':after,'successPath':success,'failurePath':failure,
          'implementationStatus':implementation,'confidence':confidence,'evidence':evidence or [],'notes':notes or []}
    node.update(extra);nodes[id]=node
    if parent: add_edge(parent,id,'contains','زیرشاخه')
    return node

def seq(ids:list[str],label:str='گام بعدی',confidence:str='high',evidence:list[dict[str,Any]]|None=None):
    for a,b in zip(ids,ids[1:]): add_edge(a,b,'sequence',label,confidence,evidence)

def flow(id:str,title:str,summary:str,node_ids:list[str],branch:str,edges_override:list[tuple[str,str,str]]|None=None):
    raw=edges_override if edges_override is not None else [(a,b,'گام بعدی') for a,b in zip(node_ids,node_ids[1:])]
    graph_edges=[]
    for a,b,lbl in raw:
        na,nb=nodes.get(a,{}),nodes.get(b,{})
        relation='state_transition' if na.get('kind')=='state' and nb.get('kind')=='state' else 'business_link' if na.get('category')!=nb.get('category') else 'sequence'
        graph_edges.append({'source':a,'target':b,'label':lbl,'relation':relation})
        add_edge(a,b,relation,lbl)
    FLOW_GROUPS.append({'id':id,'title':title,'summary':summary,'branchId':branch,'nodeIds':node_ids,'edges':graph_edges})

